#include "alp/parser.hpp"
#include <cctype>
#include <fstream>
#include <stdexcept>
namespace alp {
class Parser { std::string s; size_t p=0; void ws(){while(p<s.size()&&(std::isspace((unsigned char)s[p])||s[p]=='%')){if(s[p]=='%')while(p<s.size()&&s[p]!='\n')++p;else ++p;}} bool eat(const std::string&x){ws();if(s.compare(p,x.size(),x)==0){p+=x.size();return true;}return false;} std::string ident(){ws();size_t b=p;while(p<s.size()&&(std::isalnum((unsigned char)s[p])||s[p]=='_'||s[p]=='-'))++p;if(b==p)throw std::runtime_error("expected identifier");return s.substr(b,p-b);} Term term(){auto n=ident();if(!n.empty()&&std::isupper((unsigned char)n[0]))return Term::variable(n);if(eat("(")){std::vector<Term>a; if(!eat(")")){do{a.push_back(term());}while(eat(","));if(!eat(")"))throw std::runtime_error("expected )");}return Term::compound(n,std::move(a));}return Term::constant(n);} Atom atom(){auto n=ident();std::vector<Term>a;if(eat("(")){if(!eat(")")){do{a.push_back(term());}while(eat(","));if(!eat(")"))throw std::runtime_error("expected )");}}return Atom{Predicate{n,a.size()},std::move(a)};} Literal lit(){bool neg=eat("not");return Literal{atom(),neg};} std::vector<Literal> body(){std::vector<Literal>b;do{b.push_back(lit());}while(eat(","));return b;} public: KnowledgeBase run(){KnowledgeBase kb;while(true){ws();if(p>=s.size())break;if(eat("abducible")){if(!eat("("))throw std::runtime_error("expected (");auto n=ident();if(!eat("(")){} if(!eat(")"))throw std::runtime_error("expected )");if(!eat("."))throw std::runtime_error("expected .");kb.add_abducible(Predicate{n,0});continue;} if(eat("false")){if(!eat("<-"))throw std::runtime_error("expected <-");auto b=body();if(!eat("."))throw std::runtime_error("expected .");kb.add_constraint(IntegrityConstraint{b});continue;} Atom h=atom();if(eat(".")){kb.assert_fact(h);continue;}if(!eat("<-"))throw std::runtime_error("expected . or <-");auto b=body();if(!eat("."))throw std::runtime_error("expected .");kb.add_rule(HornClause{h,b});}return kb;} explicit Parser(std::string x):s(std::move(x)){} };
KnowledgeBase parse_program(const std::string&s){return Parser(s).run();} KnowledgeBase parse_file(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("cannot open "+path);return parse_program(std::string((std::istreambuf_iterator<char>(f)),{}));}
}
